/**
 * Content for the "human behind the code" block on /work-with-alex. Photo files
 * live in public/human-behind/ and are generated by
 * scripts/optimize-human-behind-images.py; widths here must match that script.
 */

export interface HumanBehindPhoto {
  /** File stem in public/human-behind/. */
  readonly name: string;
  /** Key under workWithAlex.humanBehind.alts and .captions. */
  readonly key: string;
  /** Pixel size of the largest generated variant; also sets the aspect ratio before load. */
  readonly width: number;
  readonly height: number;
  /** width / height; also the flex-grow factor that gives every photo in a row the same height. */
  readonly ratio: number;
  readonly srcsetWidths: readonly number[];
}

export interface GalleryPhoto extends HumanBehindPhoto {
  /** `sizes` for the photo as rendered in the page (the lightbox computes its own). */
  readonly sizes: string;
}

/** Photos that stay together on one line on phones; from md up a whole row's groups share one line. */
export interface GalleryGroup {
  readonly ratio: number;
  readonly photos: readonly GalleryPhoto[];
}

export interface GalleryRow {
  readonly groups: readonly GalleryGroup[];
}

export interface Hobby {
  /** Key under workWithAlex.humanBehind.hobbies. */
  readonly key: string;
  readonly emoji: string;
}

export interface Book {
  /** Key under workWithAlex.humanBehind.books (the one-line takeaway). */
  readonly key: string;
  readonly title: string;
  readonly author: string;
  /** Tailwind gradient classes for the little book cover. */
  readonly coverClass: string;
}

const GALLERY_WIDTHS: readonly number[] = [240, 480, 720, 1200];

function photo(name: string, key: string, width: number, height: number, srcsetWidths = GALLERY_WIDTHS) {
  return { name, key, width, height, ratio: width / height, srcsetWidths };
}

export const FEATURE_PHOTO: HumanBehindPhoto = photo('fountain', 'fountain', 1200, 1800, [400, 720, 960, 1200]);

const ROAD_TRIP = photo('road-trip', 'roadTrip', 1200, 900);
const SAILING = photo('sailing', 'sailing', 1200, 1600);
const DOG = photo('dog', 'dog', 1200, 800);
const HOME_OFFICE = photo('home-office', 'homeOffice', 1200, 1600);
const DUBAI = photo('dubai', 'dubai', 720, 960, [240, 480, 720]);
const SUIT = photo('suit', 'suit', 1200, 1800);
const VATICAN = photo('vatican', 'vatican', 720, 1280, [240, 480, 720]);
const TAORMINA = photo('taormina', 'taormina', 1200, 1806);
const GLOBE = photo('globe', 'globe', 1200, 1800);
const LAPTOP_VIEW = photo('laptop-view', 'laptopView', 1200, 1800);
const DRIVING = photo('driving', 'driving', 1200, 1600);

type PhotoInput = ReturnType<typeof photo>;

const sumRatios = (photos: readonly { ratio: number }[]) => photos.reduce((sum, p) => sum + p.ratio, 0);

/**
 * Builds a responsive `sizes` value from the photo's share of its line: lines are
 * `lgPx` wide from lg up, about `mdVw` of the viewport at md, and on phones span
 * the screen minus the layout's 40px side padding.
 */
function withSizes(p: PhotoInput, desktopLineRatio: number, mobileLineRatio: number, lgPx: number, mdVw: number) {
  const desktopShare = p.ratio / desktopLineRatio;
  const mobileShare = p.ratio / mobileLineRatio;
  const sizes =
    `(min-width: 1024px) ${Math.round(lgPx * desktopShare)}px, ` +
    `(min-width: 768px) ${Math.round(mdVw * desktopShare)}vw, ` +
    `calc((100vw - 80px) * ${mobileShare.toFixed(3)})`;
  return { ...p, sizes };
}

/** Two photos under the text, beside the portrait (560px wide from lg up). */
const ASIDE_PHOTOS = [ROAD_TRIP, SAILING];
export const ASIDE_ROW: readonly GalleryPhoto[] = ASIDE_PHOTOS.map((p) =>
  withSizes(p, sumRatios(ASIDE_PHOTOS), sumRatios(ASIDE_PHOTOS), 560, 50),
);

/** Full-width rows under the block; each inner array is one group (a line of its own on phones). */
const BOTTOM_LAYOUT: readonly (readonly (readonly PhotoInput[])[])[] = [
  [[DOG], [HOME_OFFICE, DUBAI]],
  [
    [SUIT, VATICAN, TAORMINA],
    [GLOBE, LAPTOP_VIEW, DRIVING],
  ],
];
export const BOTTOM_ROWS: readonly GalleryRow[] = BOTTOM_LAYOUT.map((row) => {
  const rowRatio = sumRatios(row.flat());
  return {
    groups: row.map((group) => ({
      ratio: sumRatios(group),
      photos: group.map((p) => withSizes(p, rowRatio, sumRatios(group), 960, 87)),
    })),
  };
});

/** Every photo in page order, which is also the lightbox's next/previous order. */
export const ALL_PHOTOS: readonly HumanBehindPhoto[] = [
  FEATURE_PHOTO,
  ...ASIDE_ROW,
  ...BOTTOM_ROWS.flatMap((row) => row.groups.flatMap((group) => group.photos)),
];

